import type {IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {useNavigate} from '@github-ui/use-navigate'
import {KebabHorizontalIcon, PencilIcon, TrashIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton} from '@primer/react'
import {useRef} from 'react'

import {Resources} from '../constants/strings'

type IssueFieldItemMenuProps = {
  issueField: IssueField
  onDelete: (issueField: IssueField, anchorButton: HTMLButtonElement | null) => void
  organization: string
}

export function IssueFieldItemMenu({issueField, onDelete, organization}: IssueFieldItemMenuProps) {
  const ref = useRef<HTMLElement | null>(null)
  const navigate = useNavigate()

  const onSelect = () => {
    navigate(`/organizations/${organization}/settings/issue-fields/${issueField.id}`)
  }

  return (
    <ActionMenu anchorRef={ref}>
      <ActionMenu.Anchor>
        <IconButton
          data-testid="overflow-menu-anchor"
          data-field-id={issueField.id}
          tooltipDirection="n"
          aria-label={`Open field options for ${issueField.name}`}
          variant="invisible"
          icon={KebabHorizontalIcon}
        />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay>
        <ActionList>
          <ActionList.Item onSelect={onSelect}>
            <ActionList.LeadingVisual>
              <PencilIcon size={16} />
            </ActionList.LeadingVisual>
            {Resources.editButton}
          </ActionList.Item>
          <ActionList.Item
            onSelect={() => {
              onDelete(issueField, ref.current as HTMLButtonElement | null)
            }}
            variant="danger"
          >
            <ActionList.LeadingVisual>
              <TrashIcon size={16} />
            </ActionList.LeadingVisual>
            {Resources.deleteButton}
          </ActionList.Item>
        </ActionList>
      </ActionMenu.Overlay>
    </ActionMenu>
  )
}

try{ IssueFieldItemMenu.displayName ||= 'IssueFieldItemMenu' } catch {}