import {Banner, Dialog, FormControl, TextInput} from '@primer/react'
import {AriaAlert} from '@primer/react/experimental'
import type {RefObject} from 'react'
import {useCallback, useEffect, useRef, useState} from 'react'

import {Resources} from '../constants/strings'
import styles from './IssueFieldDeleteConfirmationDialog.module.css'

type IssueFieldDeleteConfirmationDialogProps = {
  isOpen: boolean
  issueFieldName: string | null
  onClose: () => void
  onConfirm: () => void
  returnFocusRef: RefObject<HTMLButtonElement | null>
  error: string | null
}

export function IssueFieldDeleteConfirmationDialog({
  isOpen,
  issueFieldName,
  onClose,
  onConfirm,
  returnFocusRef,
  error,
}: IssueFieldDeleteConfirmationDialogProps) {
  const [confirmationText, setConfirmationText] = useState<string>('')
  const [showValidationError, setShowValidationError] = useState<boolean>(false)

  const isConfirmEnabled =
    confirmationText.trim().length && confirmationText.toLowerCase() === issueFieldName?.toLowerCase()

  const handleConfirm = useCallback(() => {
    if (isConfirmEnabled) {
      onConfirm()
      setConfirmationText('')
      setShowValidationError(false)
    } else {
      setShowValidationError(true)

      // Focus the input when validation fails
      setTimeout(() => {
        textInputRef.current?.focus()
      }, 0)
    }
  }, [isConfirmEnabled, onConfirm])

  const handleClose = useCallback(() => {
    setConfirmationText('')
    setShowValidationError(false)
    onClose()
  }, [onClose])

  const errorBannerRef = useRef<HTMLDivElement>(null)
  const textInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    if (error && errorBannerRef.current) {
      errorBannerRef.current.focus()
    }
  }, [error])

  if (!isOpen || !issueFieldName) {
    return null
  }

  return (
    <Dialog
      title={Resources.deleteConfirmationDialogTitle(issueFieldName)}
      width="large"
      onClose={handleClose}
      returnFocusRef={returnFocusRef}
      footerButtons={[
        {buttonType: 'default', content: Resources.cancelButton, onClick: handleClose},
        {
          buttonType: 'danger',
          content: Resources.deleteButton,
          onClick: handleConfirm,
          inactive: !isConfirmEnabled,
        },
      ]}
    >
      {error ? (
        <Banner
          className="mb-3"
          title="Error"
          description={
            // Use a div for the ref so we can focus the error banner for a11y
            <div ref={errorBannerRef} tabIndex={-1}>
              <AriaAlert>{error}</AriaAlert>
            </div>
          }
          variant="critical"
          role="alert"
        />
      ) : null}
      <div className={styles.dialogText}>{Resources.deleteConfirmationDialogBody(issueFieldName)}</div>
      <br />
      <FormControl required>
        <FormControl.Label>{Resources.deleteConfirmationFormLabel(issueFieldName)}</FormControl.Label>
        <TextInput
          ref={textInputRef}
          block
          value={confirmationText}
          placeholder={issueFieldName}
          onChange={e => setConfirmationText(e.target.value)}
        />
        {showValidationError && (
          <FormControl.Validation variant="error">{Resources.deleteConfirmationValidationError}</FormControl.Validation>
        )}
      </FormControl>
    </Dialog>
  )
}

try{ IssueFieldDeleteConfirmationDialog.displayName ||= 'IssueFieldDeleteConfirmationDialog' } catch {}