import type {SingleSelectOptionWithId} from '@github-ui/shared-single-select-components/types'

/**
 * Compares two arrays of SingleSelectOptions for equality.
 * Checks for:
 * - Length differences (added/removed options)
 * - Name changes (renamed options)
 * - Description changes
 * - Color changes
 * - Position changes (reordering)
 *
 * Returns true if arrays are identical in content and order, false otherwise.
 */
export function areOptionsEqual(a: SingleSelectOptionWithId[], b: SingleSelectOptionWithId[]): boolean {
  if (a.length !== b.length) return false

  return a.every((optA, index) => {
    const optB = b[index]
    return (
      optB !== undefined &&
      optA.name === optB.name &&
      optA.description === optB.description &&
      optA.color === optB.color
    )
  })
}
