import {KnownTypes} from '@github-ui/issue-fields-shared/issue-field'
import type {IssueFieldsUsageEvent} from '@github-ui/issue-fields-shared/issue-fields-analytics'
import {useIssueFieldsAnalytics} from '@github-ui/issue-fields-shared/use-issue-fields-analytics'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useQueryClient} from '@github-ui/react-query'
import {ssrSafeWindow} from '@github-ui/ssr-utils'
import {useCallback, useEffect, useState} from 'react'

import {IssueFieldForm, type IssueFieldFormData} from '../components/IssueFieldForm'
import {Resources} from '../constants/strings'
import {useUpdateIssueFieldMutation} from '../mutations/update-issue-field'
import {issueFieldsSettingsEditRoute} from './edit-route'

export function EditPage() {
  const payload = useRouteQuery(issueFieldsSettingsEditRoute, 'mainQuery')
  const queryClient = useQueryClient()

  const initialData = {
    id: payload.data.field.id,
    name: payload.data.field.name,
    description: payload.data.field.description,
    type: KnownTypes[payload.data.field.type],
    priority: payload.data.field.priority,
    organization: payload.data.organization.login,
    options: payload.data.field.options,
  }

  const [apiError, setApiError] = useState<string | null>(null)
  const [currentFieldName, setCurrentFieldName] = useState<string>(initialData.name)
  const [saveComplete, setSaveComplete] = useState<boolean>(false)
  const {markInteractionStart, reportUsage} = useIssueFieldsAnalytics()

  // Show error from URL param
  useEffect(() => {
    if (!ssrSafeWindow) return
    const params = new URLSearchParams(ssrSafeWindow.location.search)
    const error = params.get('error')

    if (error) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setApiError(decodeURIComponent(error))
    }
  }, [])

  useEffect(() => {
    markInteractionStart()
  }, [markInteractionStart])

  const updateMutation = useUpdateIssueFieldMutation(initialData.organization)

  const handleSave = useCallback(
    async (data: IssueFieldFormData) => {
      const startTime = Date.now()

      try {
        setApiError(null)
        setSaveComplete(false)

        // Track changes
        const changes: IssueFieldsUsageEvent['changes'] = []
        if (data.name !== initialData.name) {
          changes.push('name')
        }
        if (data.description !== initialData.description) {
          changes.push('description')
        }

        // Updated data
        const {name, description, options} = data

        const options_param = options
          ? options.map(option => {
              if (initialData.options?.some(o => o.id === option.id)) {
                return {...option, option_id: option.id}
              } else {
                return option
              }
            })
          : undefined

        await updateMutation.mutateAsync({
          id: initialData.id,
          name,
          description,
          priority: initialData.priority,
          options: options_param,
        })

        const duration = Date.now() - startTime
        reportUsage({
          page: 'org#settings',
          action: 'update',
          fieldId: initialData.id,
          fieldType: data.type.type,
          status: 'success',
          singleSelectOptionsCount: data.type === KnownTypes.single_select ? data.options?.length : undefined,
          changes: changes.length > 0 ? changes : undefined,
          duration,
          orgId: payload.data.organization.id,
        })

        // Update the current field name to reflect changes in the breadcrumb
        setCurrentFieldName(data.name)
        setSaveComplete(true)
        queryClient.invalidateQueries({queryKey: ['issue-fields-settings', 'issueFieldsSettingsIndexRoute']})
        queryClient.invalidateQueries({queryKey: ['issue-fields-settings', 'issueFieldsSettingsEditRoute']})
      } catch (error) {
        const duration = Date.now() - startTime
        reportUsage({
          page: 'org#settings',
          action: 'update',
          fieldId: initialData.id,
          fieldType: data.type.type,
          status: 'error',
          singleSelectOptionsCount: data.type === KnownTypes.single_select ? data.options?.length : undefined,
          duration,
          errorDetails: error instanceof Error ? error.message : 'Failed to update issue field',
          orgId: payload.data.organization.id,
        })

        setApiError(error instanceof Error ? error.message : 'Failed to update issue field')
      }
    },
    [
      initialData.id,
      initialData.name,
      initialData.description,
      initialData.options,
      initialData.priority,
      payload.data.organization.id,
      updateMutation,
      reportUsage,
      setCurrentFieldName,
      queryClient,
    ],
  )

  const handleFormChange = useCallback(() => {
    setSaveComplete(false)
  }, [])

  // This will be used to run duplicate name validation
  const existingFieldNames = payload.data.fields.map(field => field.name).filter(name => name !== initialData.name)

  return (
    <>
      <IssueFieldForm
        initialData={initialData}
        organizationLogin={payload.data.organization.login}
        pageTitle={currentFieldName}
        fieldNames={existingFieldNames}
        confirmLabel={Resources.saveButton}
        onSubmit={handleSave}
        error={apiError}
        typeDisabled
        cancelLabel={Resources.editPageCancelButton}
        successMessage={saveComplete}
        onFormChange={handleFormChange}
        isCreateNew={false}
      />
    </>
  )
}

try{ EditPage.displayName ||= 'EditPage' } catch {}