import type {IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {ResponseError} from '@github-ui/react-core/future/response-error'
import {useMutation} from '@github-ui/react-query'
import {reactFetch} from '@github-ui/verified-fetch'

export type UpdateIssueFieldPayload = Omit<IssueField, 'type'>
export interface UpdateIssueFieldResponse {
  success: boolean
  error?: string
  field?: IssueField
}

export async function updateIssueFieldRequest(
  payload: UpdateIssueFieldPayload,
  params: {orgName: string},
): Promise<UpdateIssueFieldResponse> {
  const {id, name, description, priority, options} = payload
  const pathname = `/organizations/${params.orgName}/settings/issue-fields/${id}`

  // Create FormData for form submission
  const formData = new FormData()
  formData.append('name', name)
  formData.append('description', description)
  formData.append('field_id', id)
  if (options) {
    formData.append('options', JSON.stringify({...options}, null, 2))
  }
  if (priority !== null && priority !== undefined) {
    formData.append('priority', priority.toString())
  }

  const response = await reactFetch(pathname, {
    method: 'PATCH',
    body: formData,
  })

  if (!response.ok) {
    // try to extract error details from the response body if there are any
    let errorDetails = ''
    try {
      const data = await response.json()
      if (data && data.error) errorDetails = `: ${data.error}`
    } catch {
      // ignore JSON parsing errors for non-JSON responses
    }
    throw new ResponseError(`Failed to update issue field ${errorDetails}`, response)
  }
  return response.json()
}

export function useUpdateIssueFieldMutation(organization: string) {
  return useMutation({
    mutationFn: async (payload: UpdateIssueFieldPayload) => {
      return updateIssueFieldRequest(payload, {orgName: organization})
    },
  })
}
