import {Button} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {Tooltip} from '@primer/react/next'
import {useRef, useState} from 'react'

import {ORGANIZATION_ISSUE_FIELDS_LIMIT} from '../constants/constants'
import {Resources} from '../constants/strings'
import styles from './IssueFieldCreateButton.module.css'

interface IssueFieldCreateButtonProps {
  organizationLogin: string
  fieldsCount: number
}

export function IssueFieldCreateButton({organizationLogin, fieldsCount}: IssueFieldCreateButtonProps) {
  const returnFocusRef = useRef(null)
  const isLimitReached = fieldsCount >= ORGANIZATION_ISSUE_FIELDS_LIMIT
  const [isDialogOpen, setIsDialogOpen] = useState(false)

  if (isLimitReached) {
    return (
      <>
        <Tooltip text={Resources.limitReachedTooltip(ORGANIZATION_ISSUE_FIELDS_LIMIT)} className={styles.tooltip}>
          <Button
            variant="primary"
            inactive={isLimitReached}
            onClick={() => setIsDialogOpen(true)}
            ref={returnFocusRef}
          >
            {Resources.createButton}
          </Button>
        </Tooltip>
        {isDialogOpen && (
          <Dialog
            onClose={() => setIsDialogOpen(false)}
            title={Resources.limitReachedDialogTitle(ORGANIZATION_ISSUE_FIELDS_LIMIT)}
            returnFocusRef={returnFocusRef}
            width="large"
          >
            {Resources.limitReachedDialogBody}
          </Dialog>
        )}
      </>
    )
  }

  return (
    <Button
      as="a"
      href={`/organizations/${organizationLogin}/settings/issue-fields/new`}
      variant="primary"
      id="create-issue-field"
    >
      {Resources.createButton}
    </Button>
  )
}

try{ IssueFieldCreateButton.displayName ||= 'IssueFieldCreateButton' } catch {}