import {mainQuery} from '@github-ui/react-core/future/main-query'

import {issueFieldsSettingsAppBuilder} from '../config/app-builder'

type DeleteIssueFieldPayload = {
  issueFieldId: number
}

export const deleteIssueFieldRoute = issueFieldsSettingsAppBuilder.createQueryRouteConfig('deleteIssueFieldRoute', {
  path: '/organizations/:org/settings/issue-fields/:issueFieldId',
  queries: [mainQuery<DeleteIssueFieldPayload>()],
})
