import {Banner} from '@primer/react'
import {useState} from 'react'

import {ORGANIZATION_ISSUE_FIELDS_LIMIT} from '../constants/constants'
import {Resources} from '../constants/strings'

interface IssueFieldsLimitReachedBannerProps {
  shouldShow: boolean
  fieldsCount: number
}

export function IssueFieldsLimitReachedBanner({shouldShow, fieldsCount}: IssueFieldsLimitReachedBannerProps) {
  const [isDismissed, setIsDismissed] = useState(false)

  const showBanner = shouldShow && fieldsCount >= ORGANIZATION_ISSUE_FIELDS_LIMIT && !isDismissed

  if (!showBanner) {
    return null
  }

  return (
    <Banner
      variant="critical"
      title={Resources.LimitReachedBannerTitle}
      hideTitle
      onDismiss={() => setIsDismissed(true)}
      className="mb-5"
    >
      {Resources.LimitReachedBannerBody(ORGANIZATION_ISSUE_FIELDS_LIMIT)}
    </Banner>
  )
}

try{ IssueFieldsLimitReachedBanner.displayName ||= 'IssueFieldsLimitReachedBanner' } catch {}