import type {IssueField} from '@github-ui/issue-fields-shared/issue-field'
import {mainQuery} from '@github-ui/react-core/future/main-query'

import {issueFieldsSettingsAppBuilder} from '../config/app-builder'
import type {Organization} from '../types/organization'

export type IssueFieldsSettingsIndexResponse = {
  fields: IssueField[]
  organization: Organization
}

export const issueFieldsSettingsIndexRoute = issueFieldsSettingsAppBuilder.createQueryRouteConfig(
  'issueFieldsSettingsIndexRoute',
  {
    path: '/organizations/:org/settings/issue-fields',
    queries: [mainQuery<IssueFieldsSettingsIndexResponse>()],
  },
)
